(function(){try{window.ORQ_FICHAS_PUT&&window.ORQ_FICHAS_PUT("L028",[{"k":"hemitartarato de zolpidem","n":"hemitartarato de zolpidem","atc":"N05CF02","cs":"2 braços","ap":[{"c":"5 mg","f":"comprimido sublingual","v":"sublingual","l":null,"r":false},{"c":"10 mg","f":"comprimido revestido","v":"oral","l":null,"r":false},{"c":"10 mg","f":"comprimido sublingual","v":"sublingual","l":null,"r":false},{"c":"2,5 mg","f":"solução spray oral","v":"oral","l":null,"r":false},{"c":"10 mg","f":"comprimido efervescente","v":"oral","l":null,"r":false},{"c":"5 mg","f":"comprimido orodispersível","v":"oral","l":null,"r":false},{"c":"10 mg/mL","f":"solução oral em gotas","v":"oral","l":null,"r":false},{"c":"2,5 mg","f":"solução oral em spray","v":"oral","l":null,"r":false}],"mc":["HEMITARTARATO DE ZOLPIDEM","INSONOX","ISOY","LUNE","LUNE SL","NOCTIDEN","NUIT FLASH","PATZ GTS"],"d":{"i":"Adultos abaixo de 65 anos: um comprimido de 10mg por dia. Adultos com idade acima de 65 anos ou com insuficiência hepática: ½ comprimido (5mg) por dia","u":"A menor dose diária efetiva de zolpidem deve ser empregada e não deve exceder 10mg","m":"A dosagem não deve exceder 10mg por dia","fr":"dose única, administrado imediatamente antes de deitar ou na cama; não deve ser readministrado na mesma noite","fo":"bula zolpidem IR, linhas 335–351"},"rn":{"t":"Na presença de insuficiência renal, com ou sem diálise, ocorre uma leve diminuição na depuração renal, mas os outros parâmetros cinéticos não são alterados. O zolpidem não é dialisável.","fo":"bula zolpidem IR, linhas 87–88"},"hp":{"t":"- Adultos com idade acima de 65 anos ou com insuficiência hepática\nConsiderando que pacientes idosos ou debilitados geralmente são mais sensíveis aos efeitos do zolpidem, recomenda-se\na administração de ½ comprimido (5mg) por dia. A dose somente deve ser aumentada para um comprimido (10mg) em\ncasos excepcionais. A dosagem não deve exceder 10mg por dia.\n- Pacientes com insuficiência hepática\nConsiderando que existe uma redução da depuração (“clearance”) e do metabolismo do zolpidem em pacientes com\ninsuficiência hepática, recomenda-se a administração de 5,0mg por dia. Esses pacientes devem ser cuidadosamente\nmonitorados, em especial em pacientes idosos. Caso a resposta clínica em adultos (abaixo de 65 anos) seja inadequada e\no medicamento bem tolerado, pode-se aumentar a dose para 10mg.","fo":"zolpidem ir · Geolab"},"ge":{"t":"Gravidez\nO uso de zolpidem não é recomendado durante a gravidez.\nEstudos em animais não indicam efeitos nocivos diretos ou indiretos em relação à toxicidade reprodutiva. O zolpidem\natravessa a placenta. Uma grande quantidade de dados coletados de estudos de coorte não demonstrou evidência de\nocorrência de malformações após exposição a benzodiazepínicos durante o primeiro trimestre de gravidez. No entanto,\nem certos estudos epidemiológicos caso-controle, observou-se aumento da incidência de fissura labial e palatina com\nbenzodiazepínicos.\nCasos de movimento fetal reduzido e variabilidade da frequência cardíaca fetal foram descritos após a administração de\nbenzodiazepínicos durante o segundo e/ou terceiro trimestre da gravidez\nA administração de zolpidem durante a fase final da gravidez ou durante o trabalho de parto, foi associada com efeitos\nno neonato, como hipotermia, hipotonia, dificuldades na alimentação (a qual pode resultar em um baixo ganho de peso)\ne depressão respiratória, em razão da ação farmacológica do produto. Casos de depressão respiratória neonatal severa\nforam reportados.\nAlém disso, crianças nascidas de mães que utilizaram sedativos/hipnóticos cronicamente durante os últimos estágios da\ngravidez podem ter desenvolvido dependência física e existe o risco de desenvolverem sintomas de abstinência após o\nnascimento. Recomenda-se adequado acompanhamento do recém-nascido no período pós-natal.\n\n\n\n\n                                                                                                        V.02 12/2024\n\fSe o hemitartarato de zolpidem for prescrito para uma mulher em idade fértil, ela deve ser alertada para entrar em\ncontato com seu médico sobre como parar o uso do produto se ela pretende ou suspeitar que está grávida.\nCategoria de risco na gravidez: categoria C. Este medicamento não deve ser utilizado por mulheres grávidas sem\norientação médica.","fo":"zolpidem ir · Geolab"},"am":{"t":"Lactação\nEmbora a concentração de zolpidem no leite materno seja baixa, ele não deve ser utilizado por mulheres durante o\nperíodo de amamentação.\nUso contraindicado no aleitamento ou na doação de leite humano.","fo":"zolpidem ir · Geolab"},"pe":{"t":"A segurança e eficácia do uso de zolpidem não foram estabelecidas em pacientes pediátricos menores de 18 anos de idade. Desta forma, o zolpidem não deve ser prescrito para esta população.","fo":"bula zolpidem IR, linhas 358–360"},"al":[{"t":"O hemitartarato de zolpidem é contraindicado em pacientes com: hipersensibilidade ao zolpidem ou a qualquer um\ndos componentes da fórmula. Este medicamento também não deve ser utilizado por pacientes com insuficiência\nrespiratória severa e/ou aguda, com insuficiência hepática severa ou em pacientes que apresentaram comportamento\ncomplexo de sono após tomar este medicamento.\nEste medicamento é contraindicado para uso por pacientes com insuficiência respiratória severa e/ou aguda\nEste medicamento é contraindicado para uso por pacientes com insuficiência hepática severa.\nEste medicamento é contraindicado para pacientes pediátricos.\nEste medicamento não deve ser usado por pessoas com síndrome de má-absorção de glicose-galactose.\n","g":"aviso"},{"t":"O uso prolongado do zolpidem não é recomendado e a duração do tratamento deve ser a menor possível, e assim como\ncom todos os hipnóticos, não deve ultrapassar a quatro semanas:\nInsônia ocasional: de 2 a 5 dias.\nInsônia transitória: de 2 a 3 semanas.\nO prolongamento do tratamento para além do período máximo não deve ocorrer sem uma reavaliação do estado do\npaciente, uma vez que o risco de abuso e dependência aumenta com a duração do tratamento (vide “Advertências e\nPrecauções”).","g":"aviso"},{"t":"Zolpidem consta da Lista B1 da Portaria SVS/MS 344/98, atualizada pela RDC 1.036/2026.","g":"aviso"},{"t":"Controle especial: zolpidem consta da Lista B1 da Portaria SVS/MS nº 344, de 12 de maio de 1998, no item «94. Zolpidem». Informação de dispensação — quem escolhe o tipo de receita no aplicativo é o médico.","g":"aviso"},{"t":"O hemitartarato de zolpidem deve ser administrado em dose única e não deve ser readministrado durante a mesma\nnoite. A menor dose diária efetiva de zolpidem deve ser empregada e não deve exceder 10mg.","g":"alta"},{"t":"O zolpidem deve ser usado com cautela em pacientes com síndrome da apneia do sono e miastenia gravis. No caso de\nsedativos/hipnóticos com curta duração de ação, pode ocorrer o fenômeno de retirada durante intervalo de dose.","g":"aviso"},{"t":"O rápido início da sedação, associado às características amnésicas do hemitartarato de zolpidem, particularmente\nquando combinado com álcool, administrado sem o conhecimento da vítima, provou induzir incapacidade e, assim,\nfacilitar ações criminosas (que podem ser perigosas).\nOs prestadores de cuidados de saúde devem prescrever o hemitartarato de zolpidem de acordo com a sua avaliação\nclínica e apenas em caso de necessidade médica, uma vez que pode ser utilizada ilicitamente para submissão química.","g":"alta"},{"t":"Pacientes que dirigem veículos ou operam máquinas devem ser alertados para a possibilidade de risco de reações\nadversas incluindo sonolência, tempo de reação prolongado, tontura, visão borrada ou visão dupla e redução do estado\nde alerta e condução prejudicada na manhã seguinte à administração de zolpidem. Para minimizar este risco,\nrecomenda-se que a duração do sono seja de 7-8 horas.","g":"aviso"},{"t":"VENDA SOB PRESCRIÇÃO - O ABUSO DESTE MEDICAMENTO PODE CAUSAR DEPENDÊNCIA.","g":"aviso"}],"rx":[{"id":"l028-zolpidem-ir-10mg-com-rev","t":"Hemitartarato de zolpidem 10 mg","p":"Hemitartarato de zolpidem 10 mg/comprimido revestido — 30 comprimidos/mês.\nTomar 1 comprimido, via oral, 1 vez ao dia, imediatamente antes de deitar.","o":"O hemitartarato de zolpidem deve ser administrado em dose única e não deve ser readministrado na mesma noite.","fo":"Bula do profissional — HEMITARTARATO DE ZOLPIDEM (medicamento genérico, Lei nº 9.787/1999), comprimido revestido 10 mg, Geolab Indústria Farmacêutica S/A…","dt":"receita_controle_especial"}]},{"k":"hemitartarato de zolpidem [LP]","n":"hemitartarato de zolpidem","atc":"N05CF02","cs":"2 braços","ap":[{"c":"6,25 mg","f":"comprimido revestido de liberação prolongada","v":"oral","l":null,"r":false},{"c":"12,5 mg","f":"comprimido revestido de liberação prolongada","v":"oral","l":null,"r":false},{"c":"6,25 mg","f":"comprimido de liberação prolongada","v":"oral","l":null,"r":false},{"c":"12,5 mg","f":"comprimido de liberação prolongada","v":"oral","l":null,"r":false}],"mc":["HEMITARTARATO DE ZOLPIDEM","NUIT LONG XR","PATZ CR","STILNOX","TURNO XR"],"d":{"i":"Adultos abaixo de 65 anos: 2 comprimidos de 6,25 mg ao dia; ou 1 comprimido de 12,5 mg ao dia","u":"Adultos abaixo de 65 anos: 2 comprimidos de 6,25 mg ao dia; ou 1 comprimido de 12,5 mg ao dia","m":"A menor dose diária efetiva de zolpidem deve ser empregada e não deve exceder 12,5 mg","fr":"dose única, administrado por via oral imediatamente antes de deitar ou na cama; não deve ser readministrado na mesma noite","fo":"bula zolpidem LP, linhas 399–404"},"rn":{"t":"Não é necessário ajuste de dose nesses pacientes.","fo":"bula zolpidem LP, linhas 412–413"},"hp":{"t":"Considerando que existe uma redução do “clearance” e do metabolismo do zolpidem em pacientes com insuficiência hepática, recomenda-se a administração de 1 comprimido de 6,25 mg por dia. Esses pacientes devem ser cuidadosamente monitorados, em especial em pacientes idosos. STILNOX CR não deve ser utilizado em pacientes com insuficiência hepática severa.","fo":"bula zolpidem LP, linhas 406–410"},"ge":{"t":"O uso de zolpidem não é recomendado durante a gravidez. Categoria de risco na gravidez: categoria C.","fo":"texto extraído com `pdftotext -layout` do PDF oficial, ambos…"},"am":{"t":"Embora a concentração de zolpidem no leite materno seja baixa, ele não deve ser utilizado por mulheres durante o período de amamentação. Uso contraindicado no aleitamento ou na doação de leite humano.","fo":"bula zolpidem LP, linhas 288–291"},"pe":{"t":"A segurança e eficácia do uso de zolpidem não foram estabelecidas em pacientes pediátricos menores de 18 anos de idade. Desta forma, o zolpidem não deve ser prescrito para esta população.","fo":"bula zolpidem LP, linhas 415–418"},"al":[{"t":"Zolpidem consta da Lista B1 da Portaria SVS/MS 344/98, atualizada pela RDC 1.036/2026.","g":"aviso"},{"t":"Controle especial: zolpidem consta da Lista B1 da Portaria SVS/MS nº 344, de 12 de maio de 1998, no item «94. Zolpidem». Informação de dispensação — quem escolhe o tipo de receita no aplicativo é o médico.","g":"aviso"},{"t":"4. CONTRAINDICAÇÕES\nSTILNOX CR está contraindicado em pacientes com: hipersensibilidade ao zolpidem ou a qualquer um dos\ncomponentes da fórmula. Este medicamento também não deve ser utilizado por pacientes com insuficiência\nrespiratória severa e/ou aguda, com insuficiência hepática severa ou em pacientes que apresentaram comportamento\ncomplexo de sono após tomar este medicamento.\n\nEste medicamento é contraindicado para uso por pacientes com insuficiência respiratória severa e/ou aguda\nEste medicamento é contraindicado para uso por pacientes com insuficiência hepática severa.\nEste medicamento é contraindicado para pacientes pediátricos.\nEste medicamento não deve ser usado por pessoas com síndrome de má-absorção de glicose-galactose.\n\n5. ADVERTÊNCIAS E PRECAUÇÕES\nADVERTÊNCIAS\nO zolpidem deve ser usado com cautela em pacientes com síndrome da apneia do sono e miastenia gravis. No caso de\nsedativos/hipnóticos com curta duração de ação, pode ocorrer o fenômeno de retirada durante intervalo de dose.\nSTILNOX CR deve ser administrado em dose única e não deve ser readministrado durante a mesma noite. A menor\ndose diária efetiva de zolpidem deve ser empregada e não deve exceder 12,5 mg.\n\n    •    Insuficiência respiratória\n\n                                                                                                                         2\n\fComo os hipnóticos têm a capacidade de causar depressão respiratória, precauções devem ser adotadas se o zolpidem\nfor prescrito a pacientes com a função respiratória comprometida (vide “Reações Adversas”).\n\n    • Risco do uso concomitante com opioides\nO uso concomitante de opioides com benzodiazepínicos ou outros fármacos hipnóticos sedativos, incluindo o\nzolpidem, pode resultar em sedação, depressão respiratória, coma e óbito. Em virtude destes riscos, reserve a\nprescrição concomitante de opioides e benzodiazepínicos para o uso em pacientes nos quais as alternativas terapêuticas\ndisponíveis sejam inadequadas.\n\nCaso seja decidido pela prescrição de zolpidem concomitantemente com opioides, prescreva a menor dose eficaz com\nduração mínima de uso concomitante, e acompanhe o paciente de perto quanto aos sinais e sintomas de depressão\nrespiratória e sedação (vide “Interações Medicamentosas”).\n\n    • Insuficiência hepática\nO zolpidem não deve ser utilizado em pacientes com insuficiência hepática severa uma vez que pode contribuir para\nencefalopatia. Vide “Posologia e Modo de Usar”, “Contraindicações” e “Reações Adversas”.\n\nPRECAUÇÕES\nA causa primária da insônia deve ser identificada sempre que possível e os fatores causais tratados antes da prescrição\nde um hipnótico. A falta de efeito do tratamento após 7 a 14 dias de uso pode indicar a presença de um distúrbio\npsiquiátrico primário ou uma desordem física devendo o paciente ser reavaliado cuidadosamente em intervalos\nregulares.\n\n     • Pacientes pediátricos\nA segurança e eficácia de zolpidem em pacientes com idade inferior a 18 anos não foram estabelecidas. Portanto, o\nzolpidem não deve ser prescrito a crianças. Um estudo com duração de 8 semanas, realizado em pacientes pediátricos\n(6 - 17 anos) com insônia associada a déficit de atenção/hiperatividade, distúrbios psiquiátricos e do sistema nervoso,\nrevelou as reações adversas mais frequentemente observadas no tratamento com o zolpidem “versus” placebo e incluiu\ntontura (23,5% “versus” 1,5%), dor de cabeça (12,5% “versus” 9,2%) e alucinações (7,4% “versus” 0%) (vide\n“Posologia e Modo de Usar – Populações Especiais”).\n\n    • Pacientes idosos\nVide recomendações no item “Posologia - Adultos com idade acima de 65 anos ou pacientes debilitados”.\n\n    • Pacientes com doença psicótica\nHipnóticos como o zolpidem não devem ser a medicação principal para o tratamento de pacientes psicóticos.\n\n    • Amnésia\nSedativos e hipnóticos como o zolpidem, podem causar amnésia anterógrada, que em geral ocorre algumas horas após\nadministração. Por essa razão, aconselha-se tomar o medicamento imediatamente antes de deitar, sendo importante\nassegurar condições favoráveis para um sono ininterrupto de 7-8 horas.\n\n    • Ideação suicida e depressão\nVários estudos epidemiológicos demonstraram um aumento da incidência de suicídio e tentativa de suicídio em\npacientes com ou sem depressão, tratados com benzodiazepínicos e outros hipnóticos, incluindo o zolpidem. A relação\ncausal não foi estabelecida.\n\nComo acontece com outros medicamentos sedativos/hipnóticos, o zolpidem deve ser administrado com cautela em\npacientes que apresentam sintomas de depressão e que podem apresentar tendências suicidas. A menor dose possível\ndeve ser empregada nesses pacientes para evitar a superdose intencional. Depressão pré-existente pode ser\ndesmascarada durante o uso de zolpidem. Considerando que insônia pode ser um sintoma de depressão, o paciente\ndeve ser reavaliado caso ela persista.\n\n     • Outras reações psiquiátricas e “paradoxais”\nOutras reações psiquiátricas e paradoxais como nervosismo, exacerbação da insônia, pesadelos, irritabilidade,\nagitação, agressividade, ilusões, acessos de raiva, alucinações, comportamento inapropriado e outros distúrbios de\ncomportamento, podem ocorrer com o uso de sedativos e hipnóticos, como o zolpidem. Nesse caso, o medicamento\ndeve ser descontinuado. Essas reações são mais prováveis de ocorrer em idosos.\n\n                                                                                                                          3\n\f     • Sonambulismo e comportamentos associados\nComportamentos complexos de sono, incluindo dormir enquanto caminha, dormir enquanto dirige, e engajar em outras\natividades enquanto não estiver totalmente acordado, podem ocorrer após o primeiro ou qualquer uso subsequente\ndeste medicamento. Pacientes podem ferir-se gravemente ou ferir outros indivíduos durante esses comportamentos.\nEssas lesões podem ser fatais. Outros comportamentos de sono associados (por exemplo, enquanto prepara e come\nalimentos, faz ligações ou atos sexuais) também foram reportados, acompanhado de amnésia para estes eventos.\nRelatos de pós-comercialização mostram que comportamentos complexos de sono podem ocorrer com a administração\nisolada deste medicamento a doses recomendadas, com ou sem uso concomitante de álcool ou outros depressores do\nsistema nervoso central (SNC) (vide \"Interações Medicamentosas\"). Se o paciente apresentar algum destes\ncomportamentos, a descontinuação imediata deste medicamento é recomendada. (vide item \"Contraindicações?”.\n\n   • Comprometimento psicomotor\nComo outros medicamentos sedativos/hipnóticos, o zolpidem tem efeitos de depressão do SNC.\n\nO risco de comprometimento psicomotor, incluindo prejuízo na habilidade de dirigir, é aumentado se o zolpidem é\nadministrado em menos de 7-8 horas antes o início das atividades que requerem alerta mental; se é utilizada uma dose\nmais alta que a recomendada; ou se o zolpidem é coadministrado com outros depressores do SNC, álcool, ou com\noutros medicamentos que elevam a concentração sanguínea de zolpidem (vide “Interações Medicamentosas” e\n“Advertências e Precauções - Alterações na capacidade de dirigir veículos e operar máquinas”).\n\n    • Tolerância\nAlguns sedativos/hipnóticos como o zolpidem podem apresentar perda de eficácia dos efeitos hipnóticos após uso\nprolongado por algumas semanas.\n\n     • Dependência\nO uso do zolpidem, pode levar ao desenvolvimento de abuso e/ou dependência física ou psíquica. O risco de\ndependência aumenta com a dose e a duração do tratamento. Casos de dependência foram relatados com maior\nfrequência em pacientes tratados com STILNOX CR por mais de 4 semanas. O risco de abuso e dependência é também\nmaior em pacientes com histórico de distúrbios psiquiátricos e/ou abuso de álcool ou drogas. STILNOX CR deve ser\nutilizado com extrema cautela em pacientes em uso ou com histórico de abuso de álcool e drogas.\nNa presença de dependência física, a descontinuação abrupta do zolpidem pode causar o aparecimento de sintomas de\nabstinência: cefaleia, dor muscular, ansiedade e tensão extremas, agitação, confusão e irritabilidade. Em casos severos,\nos seguintes sintomas podem ocorrer: desrealização, despersonalização, hiperacusia, dormência e formigamento das\nextremidades, hipersensibilidade à luz, barulho e a contatos físicos, alucinações, “delirium” e convulsões.\n\n     • Insônia de rebote\nA interrupção abrupta de um tratamento com hipnóticos em posologia e duração acima das recomendadas pode\nprovocar insônia de rebote transitória (reaparecimento de insônia às vezes mais grave do que aquela que motivou o\ntratamento) e pode também causar outros sintomas (alterações do humor, ansiedade, agitação). Portanto, é importante\nque o paciente seja alertado quanto a este fenômeno e a posologia deve ser reduzida gradualmente para minimizá-lo.\nNo caso de sedativos/hipnóticos com curta duração de ação, o fenômeno de retirada pode se manifestar dentro do\nintervalo de dose.\n\n    • Lesões severas\nDevido às suas propriedades farmacológicas, o zolpidem pode causar sonolência e diminuição do nível de consciência,\nque pode levar a quedas e, consequentemente, a lesões severas.\n\n    • Pacientes com síndrome do QT longo\nUm estudo eletrofisiológico cardíaco “in vitro” demonstrou que sob condições experimentais, utilizando\nconcentrações muito altas e pluripotentes de células tronco, o zolpidem pode reduzir o hERG relacionado aos canais\nde potássio.\n\nEste medicamento pode potencializar o prolongamento do intervalo QT, o que aumenta o risco de ataque de\narritmias ventriculares graves do tipo \"torsades de pointes\", que é potencialmente fatal (morte súbita).\n\nAs consequências potenciais em pacientes com síndrome do QT longo congênito são desconhecidas. Como precaução,\na relação benefício/risco do tratamento com o zolpidem em pacientes diagnosticados com síndorme do QT longo\ncongênicto deve ser cuidadosamente considerada.\n\n\n                                                                                                                           4\n\f    • Submissão química (uso ilícito de drogas para fins criminosos)\nO rápido início da sedação, associado às características amnésicas do STILNOX, particularmente quando combinado\ncom álcool, administrado sem o conhecimento da vítima, provou induzir incapacidade e, assim, facilitar ações\ncriminosas (que podem ser perigosas).\nOs prestadores de cuidados de saúde devem prescrever o STILNOX de acordo com a sua avaliação clínica e apenas\nem caso de necessidade médica, uma vez que pode ser utilizada ilicitamente para submissão química.\n\nGravidez\nO uso de zolpidem não é recomendado durante a gravidez.\n\nEstudos em animais não indicam efeitos nocivos diretos ou indiretos em relação à toxicidade reprodutiva.\n\nO zolpidem atravessa a placenta.\n\nUma grande quantidade de dados coletados de estudos de coorte não demonstrou evidência de ocorrência de\nmalformações após exposição a benzodiazepínicos durante o primeiro trimestre de gravidez. No entanto, em certos\nestudos epidemiológicos caso-controle, observou-se aumento da incidência de fissura labial e palatina com\nbenzodiazepínicos.\n\nCasos de redução do movimento fetal reduzido e variabilidade da frequência cardíaca fetal foram descritos após a\nadministração de benzodiazepínicos durante o segundo e/ou terceiro trimestre da gravidez\n\nA administração de zolpidem durante a fase final da gravidez ou durante o trabalho de parto, foi associada com efeitos\nno neonato como hipotermia, hipotonia, dificuldades na alimentação (a qual pode resultar em um baixo ganho de\npeso) e depressão respiratória, em razão da ação farmacológica do produto. Casos de depressão respiratória neonatal\nsevera foram reportados.\n\nAlém disso, crianças nascidas de mães que utilizaram sedativos/hipnóticos cronicamente durante os últimos estágios\nda gravidez podem ter desenvolvido dependência física e existe o risco de desenvolverem sintomas de abstinência\napós o nascimento. Recomenda-se adequado acompanhamento do recém-nascido no período pós-natal.\n\nSe STILNOX CR for prescrito para uma mulher em idade fértil, ela deve ser alertada para entrar em contato com seu\nmédico sobre como parar o uso do produto, se ela pretende ou suspeita de que está grávida.\n\nCategoria de risco na gravidez: categoria C. Este medicamento não deve ser utilizado por mulheres grávidas\nsem orientação médica.\n\nLactação\nEmbora a concentração de zolpidem no leite materno seja baixa, ele não deve ser utilizado por mulheres durante o\nperíodo de amamentação.\n\nUso contraindicado no aleitamento ou na doação de leite humano. Este medicamento é contraindicado durante\no aleitamento ou doação de leite, pois é excretado no leite humano e pode causar reações indesejáveis no bebê.\nSeu médico ou cirurgião-dentista deve apresentar alternativas para o seu tratamento ou para a alimentação do\nbebê.\n\nAlterações na capacidade de dirigir veículos e operar máquinas\nPacientes que dirigem veículos ou operam máquinas devem ser alertados para a possibilidade de risco de reações\nadversas incluindo sonolência, tempo de reação prolongado, tontura, visão borrada ou visão dupla e redução do estado\nde alerta e condução prejudicada na manhã seguinte à administração de zolpidem. Para minimizar este risco,\nrecomenda-se que a duração do sono seja de 7-8 horas.\n\nOriente seu paciente a não dirigir veículos ou operar máquinas durante todo o tratamento, pois sua habilidade\ne capacidade de reação podem estar prejudicadas.\n\nO uso deste medicamento pode causar tontura, desmaios ou perda da consciência, expondo o paciente a quedas\nou acidentes.\n\n\n\n                                                                                                                         5\n\fAlém disto, a coadministração de zolpidem com álcool e outros depressores do SNC aumentam o risco destes efeitos.\nOs pacientes devem ser advertidos para não consumir álcool ou outros medicamentos psicoativos enquanto utilizar o\nzolpidem.\n\nAtenção: Contém lactose (tipo de açúcar) abaixo de 0,25g por comprimido.\nAtenção: Contém os corantes dióxido de titânio e óxido de ferro vermelho.\n\nInforme a seu paciente que a doação de sangue é absolutamente contraindicada durante o tratamento com\ndoses altas de Stilnox CR (zolpidem), devido ao dano que pode causar ao receptor.\n\n6. INTERAÇÕES MEDICAMENTOSAS\n     • Álcool\nA ingestão de STILNOX CR juntamente com bebidas alcoólicas ou de medicamentos contendo álcool não é\nrecomendada. O efeito sedativo pode ser potencializado quando STILNOX CR é administrado em combinação com\nálcool além de afetar a capacidade de dirigir ou operar máquinas.\n\n     • Depressores do SNC\nO aumento da depressão do Sistema Nervoso Central pode ocorrer no caso de uso concomitante com antipsicóticos\n(neurolépticos), hipnóticos, ansiolíticos/sedativos, agentes antidepressivos, analgésicos narcóticos, drogas\nantiepiléticas, anestésicos e anti-histamínicos. O uso concomitante de zolpidem com estes medicamentos podem\naumentar a sonolência e o comprometimento psicomotor, incluindo a habilidade de dirigir. No caso de analgésicos\nnarcóticos, pode ocorrer aumento da sensação de euforia levando a ocorrência de dependência psicológica.\n\n    • Opioides\nO uso concomitante de benzodiazepínicos e outros fármacos hipnóticos sedativos, incluindo o zolpidem, e opioides,\naumenta o risco de sedação, depressão respiratória, coma e óbito devido ao efeito aditivo depressor do SNC. Se o uso\nconcomitante for necessário, limite a dose e a duração do uso concomitante de benzodiazepínicos e opioides (vide\n“Advertências e Precauções”).\n\n    • Inibidores e indutores da CYP450\nCompostos que inibem o citocromo P450 podem aumentar a atividade de alguns hipnóticos como o zolpidem. O\nzolpidem é metabolizado por várias enzimas hepáticas do citocromo P450: sendo as principais CYP3A4 com a\ncontribuição da CYP1A2. O efeito farmacodinâmico do zolpidem é menor quando é administrado com um indutor da\nCYP3A4 tal como a rifampicina e a Erva de São João. A Erva de São João mostrou ter uma interação farmacocinética\ncom o zolpidem. A Cmáx e a AUC médias foram diminuídas (33,7 e 30,0%, inferiores, respectivamente) para o\nzolpidem administrado com Erva de São João em comparação com o zolpidem administrado isoladamente. A\ncoadministração da Erva de São João pode diminuir os níveis sanguíneos de zolpidem. O uso concomitante não é\nrecomendado.\n\nEntretanto, quando o zolpidem foi administrado com o itraconazol (um inibidor do CYP3A4), a farmacocinética e a\nfarmacodinâmica, não foram significativamente modificadas. A relevância clínica destes resultados não é conhecida.\nA coadministração de zolpidem com o cetoconazol (200 mg, duas vezes ao dia), um potente inibidor CYP3A4,\nprolonga a meia-vida de eliminação do zolpidem, aumenta o AUC total e diminui o “clearance” quando comparado\ncom o zolpidem mais placebo. Quando coadministrado com o cetoconazol, o AUC total aumenta modestamente (fator\n1,83 quando comparado com o zolpidem sozinho). Um ajuste de dosagem de zolpidem não é necessário, mas os\npacientes devem ser advertidos que a coadministração de zolpidem com cetoconazol pode aumentar os efeitos\nsedativos.\n\nA fluvoxamina é um potente inibidor da CYP1A2 e de moderado a fraco inibidor da CYP2C9 e CYP3A4. A\ncoadministração de fluvoxamina pode aumentar os níveis sanguíneos de zolpidem. O uso concomitante não é\nrecomendado.\n\nO ciprofloxacino tem se mostrado um moderado inibidor da CYP1A2 e CYP3A4. A coadministração de\nciprofloxacino pode aumentar os níveis sanguíneos de zolpidem. O uso concomitante não é recomendado.\n\n    • Outros medicamentos\nQuando o zolpidem foi administrado junto com a varfarina, a digoxina, a ranitidina ou a cimetidina, nenhuma interação\nfarmacocinética foi observada.\n\n\n                                                                                                                        6\n\f7. CUIDADOS DE ARMAZENAMENTO DO MEDICAMENTO\nSTILNOX CR deve ser mantido em temperatura ambiente (entre 15 e 30°C).\n\nPrazo de validade: 36 meses a partir da data de fabricação.\nNúmero de lote e datas de fabricação e validade: vide embalagem.\nNão use medicamento com o prazo de validade vencido. Guarde-o em sua embalagem original.\n\nCaracterísticas físicas e organolépticas\nComprimidos redondos e biconvexos de coloração rosa, com a gravação ZMR em uma\ndas faces.\n\nAntes de usar, observe o aspecto do medicamento.\nTodo medicamento deve ser mantido fora do alcance das crianças.\n\n8. POSOLOGIA E MODO DE USAR\nSTILNOX CR age rapidamente e por isso, deve ser sempre administrado por via oral imediatamente antes de deitar\nou na cama. STILNOX CR deve ser administrado em dose única e não deve ser readministrado na mesma noite.\n\nO uso prolongado de zolpidem não é recomendado e a duração do tratamento, deve ser a menor possível, e assim\ncomo para todos os hipnóticos, não deve ultrapassar quatro semanas:\n\n-Insônia ocasional: de 2 a 5 dias\n-Insônia transitória: de 2 a 3 semanas\n O prolongamento do tratamento para além do período máximo não deve ocorrer sem uma reavaliação do estado do\npaciente, uma vez que o risco de abuso e dependência aumenta com a duração do tratamento (vide “Advertências e\nPrecauções”).\n\nAdultos abaixo de 65 anos: 2 comprimidos de 6,25 mg ao dia.\n\nPopulação Especial\n- Adultos com idade acima de 65 anos ou pacientes debilitados\nConsiderando que pacientes idosos ou debilitados geralmente são mais sensíveis aos efeitos do zolpidem, recomenda-\nse a administração de 1 comprimido de 6,25 mg ao dia.\n\n- Pacientes com insuficiência hepática\nConsiderando que existe uma redução do “clearance” e do metabolismo do zolpidem em pacientes com insuficiência\nhepática, recomenda-se a administração de 1 comprimido de 6,25 mg por dia. Esses pacientes devem ser\ncuidadosamente monitorados, em especial em pacientes idosos. STILNOX CR não deve ser utilizado em pacientes\ncom insuficiência hepática severa.\n\n- Pacientes com insuficiência renal\nNão é necessário ajuste de dose nesses pacientes.\n\n- Pacientes Pediátricos\nA segurança e eficácia do uso de zolpidem não foram estabelecidas em pacientes pediátricos menores de 18 anos de\nidade. Desta forma, o zolpidem não deve ser prescrito para esta população (vide “Advertências e Precauções – Uso\nPediátrico”).\n\nLiberação do princípio ativo\nO STILNOX CR apresenta uma liberação imediata de 60% do princípio ativo, e o restante da dose (40%) é liberado\nde maneira prolongada. Em comparação ao zolpidem de liberação imediata, a máxima diferença de concentração\nsérica entre as duas apresentações foi observada entre 3 a 6 horas após a dose.\n\nRisco de uso por via de administração não recomendada\nNão há estudos dos efeitos de STILNOX CR administrado por vias não recomendadas. Portanto, por segurança e para\ngarantir a eficácia deste medicamento, a administração deve ser somente pela via oral.\n\nEste medicamento não deve ser partido, aberto ou mastigado.\n\n\n                                                                                                                     7\n\f9. REAÇÕES ADVERSAS\nExistem evidências de que as reações adversas, particularmente certas reações no SNC, estão relacionadas com a dose.\nEssas reações, em teoria, devem ser menores se o zolpidem é administrado imediatamente antes do paciente deitar-se\nou na cama. Essas reações ocorrem com mais frequência em pacientes idosos e no início da terapia. De acordo com\nas recomendações da CIOMS, têm-se utilizado os seguintes índices de frequência:\n\nReação muito comum (≥ 1/10)\nReação comum (≥ 1/100 e  1/10)\nReação incomum (≥ 1/1.000 e  1/100)\nReação rara (≥ 1/10.000 e  1/1.000)\nReação muito rara ( 1/10.000)\nDesconhecida (não podem ser estimados a partir dos dados disponíveis).\n\nAs reações adversas reportadas no grupo recebendo o zolpidem com uma incidência maior que no grupo do placebo\nem estudos clínicos são descritos abaixo:\n\nInfecções e infestações\nComum: influenza.\nIncomuns: gastroenterite, labirintite, infecção do trato respiratório inferior e superior e otite externa.\n\nDistúrbios do sistema imunológico\nDesconhecida: edema angioneurótico.\n\nDistúrbios nutricionais e do metabolismo\nIncomum: distúrbios do apetite.\n\nDistúrbios psiquiátricos\nComuns: ansiedade, atraso psicomotor e desorientação.\nIncomuns: agitação, agressividade, sonambulismo (vide “Advertências e Precauções”), depressão, alucinação\nincluindo alucinações visuais e hipnagógicas, apatia, regozijo ao comer, confusão, despersonalização, humor\ndeprimido, desinibição, euforia, mudança de humor, pesadelo, sintomas de estresse.\nRara: distúrbios da líbido.\nMuito raras: desilusão e dependência (sintomas de abstinência ou efeitos de repercussão podem ocorrer após a\ndescontinuação do tratamento).\nDesconhecidas: acessos de raiva, comportamento inapropriado, comportamento complexo de sono, “delirium” (vide","g":"contraindicacao"},{"t":"dose diária efetiva de zolpidem deve ser empregada e não deve exceder 12,5 mg.","g":"alta"},{"t":"O uso prolongado de zolpidem não é recomendado e a duração do tratamento, deve ser a menor possível, e assim\ncomo para todos os hipnóticos, não deve ultrapassar quatro semanas:\n\n-Insônia ocasional: de 2 a 5 dias\n-Insônia transitória: de 2 a 3 semanas","g":"alta"},{"t":"STILNOX CR age rapidamente e por isso, deve ser sempre administrado por via oral imediatamente antes de deitar\nou na cama. STILNOX CR deve ser administrado em dose única e não deve ser readministrado na mesma noite.","g":"aviso"},{"t":"O STILNOX CR apresenta uma liberação imediata de 60% do princípio ativo, e o restante da dose (40%) é liberado\nde maneira prolongada. Em comparação ao zolpidem de liberação imediata, a máxima diferença de concentração\nsérica entre as duas apresentações foi observada entre 3 a 6 horas após a dose.","g":"informativo"},{"t":"VENDA SOB PRESCRIÇÃO - O ABUSO DESTE MEDICAMENTO PODE CAUSAR DEPENDÊNCIA.","g":"aviso"}],"rx":[{"id":"l028-zolpidem-lp-6-25mg-com-lib-prol","t":"Hemitartarato de zolpidem 6,25 mg liberação prolongada","p":"Hemitartarato de zolpidem 6,25 mg/comprimido de liberação prolongada — 60 comprimidos/mês.\nTomar 2 comprimidos, via oral, 1 vez ao dia, imediatamente antes de deitar.","o":"STILNOX CR deve ser administrado em dose única e não deve ser readministrado na mesma noite.","fo":"Bula do profissional — STILNOX® CR (hemitartarato de zolpidem), comprimidos de liberação prolongada 6,25 mg e 12,5 mg, Sanofi Medley Farmacêutica Ltda…","dt":"receita_controle_especial"},{"id":"l028-zolpidem-lp-12-5mg-com-lib-prol","t":"Hemitartarato de zolpidem 12,5 mg liberação prolongada","p":"Hemitartarato de zolpidem 12,5 mg/comprimido de liberação prolongada — 30 comprimidos/mês.\nTomar 1 comprimido, via oral, 1 vez ao dia, imediatamente antes de deitar.","o":"STILNOX CR deve ser administrado em dose única e não deve ser readministrado na mesma noite.","fo":"Bula do profissional — STILNOX® CR (hemitartarato de zolpidem), comprimidos de liberação prolongada 6,25 mg e 12,5 mg, Sanofi Medley Farmacêutica Ltda…","dt":"receita_controle_especial"}]},{"k":"lemborexante","n":"lemborexante","atc":"N05CJ02","cs":"2 braços","ap":[{"c":"5 mg","f":"comprimido revestido","v":"oral","l":null,"r":false},{"c":"10 mg","f":"comprimido revestido","v":"oral","l":null,"r":false}],"mc":["DAYVIGO"],"d":{"i":"A dose recomendada de DAYVIGO® é de 5 mg, administrada não mais que uma vez por noite, e alguns minutos antes de ir para a cama, com pelo menos 7 horas restantes antes da hora planejada de despertar","u":"A dose pode ser aumentada para a dose máxima recomendada de 10 mg com base na resposta clínica e tolerabilidade do paciente; DAYVIGO® deve ser utilizado na dose mais baixa e durante o menor período, conforme clinicamente indicado","m":"A dose máxima recomendada de DAYVIGO® é de 10 mg, uma vez ao dia","fr":"não mais que uma vez por noite, alguns minutos antes de ir para a cama; o tempo para o início do sono pode demorar, se administrado logo após ou com uma refeição","fo":"ANVISA · anvisa dayvigo lemborexante ficha, linhas 55–56…"},"rn":{"t":"Nenhum ajuste de dose é recomendado para pacientes com insuficiência renal.","fo":"ANVISA · anvisa dayvigo lemborexante ficha. A mesma linha da página…"},"hp":{"t":"Pacientes com insuficiência hepática moderada devem usar a dose máxima de 5 mg e o uso não é recomendado em pacientes com insuficiência hepática grave.","fo":"ANVISA · anvisa dayvigo lemborexante ficha. A mesma linha da página…"},"ge":{"t":"O uso em mulheres gestantes não é recomendado.","fo":"diretriz lemborexante, linhas 2774–2777. Seção…"},"am":{"t":"O uso durante a amamentação não é recomendado.","fo":"diretriz lemborexante, linhas 2774–2777. Seção…"},"pe":{"t":"A segurança e a eficácia do lemborexante não foram estabelecidas em pacientes pediátricos (abaixo de 18 anos de idade). DAYVIGO® não é recomendado em pacientes pediátricos.","fo":"anvisa dayvigo lemborexante ficha. Reforço na diretriz da…"},"al":[{"t":"Lemborexante consta da Lista B1 da Portaria SVS/MS 344/98, atualizada pela RDC 1.036/2026.","g":"aviso"},{"t":"Controle especial: lemborexante consta da Lista B1 da Portaria SVS/MS nº 344, de 12 de maio de 1998, no item «54. Lemborexante». Informação de dispensação — quem escolhe o tipo de receita no aplicativo é o médico.","g":"aviso"},{"t":"Este medicamento só pode ser vendido com retenção da receita – Lista B1 da Portaria 344/1998.","g":"aviso"},{"t":"Alguns riscos potenciais identificados para o medicamento incluem as interações medicamentosas, os sintomas de narcolepsia e o potencial de abuso. DAYVIGO® é contraindicado em pacientes com narcolepsia (distúrbio do sono caracterizado por sonolência excessiva durante o dia, mesmo quando a pessoa dormiu bem à noite).","g":"contraindicacao"},{"t":"O lemborexante não deve ser usado com inibidores ou indutores moderados a fortes do CYP3A e os pacientes devem ser orientados a não consumir álcool em combinação com o medicamento.","g":"alta"},{"t":"Quanto à capacidade de dirigir, os pacientes que usam a dose de 10 mg devem ser alertados sobre o potencial de comprometimento no desempenho da condução de veículos na manhã seguinte, uma vez que há uma variação individual na sensibilidade ao lemborexante.","g":"aviso"},{"t":"Os pacientes devem ser aconselhados a não consumir álcool em combinação com DAYVIGO®.","g":"aviso"},{"t":"Controle de importação e exportação: o adendo 11 da Lista B1 dispensa de Autorização de Importação e de Exportação os padrões analíticos à base de lemborexante, entre outras substâncias, quando a quantidade do ativo sujeito a controle especial não excede 500 mg por unidade.","g":"informativo"},{"t":"Confirmação no Diário Oficial da União: a Resolução Anvisa nº 970, de 19 de março de 2025, publicou a atualização do Anexo I (Listas de Substâncias Entorpecentes, Psicotrópicas, Precursoras e Outras sob Controle Especial) da Portaria SVS/MS nº 344, de 12 de maio de 1998, com a INCLUSÃO «1.1. Lista \"B1\": lemborexante» e a ALTERAÇÃO «2.1. Lista \" B1\": adendo 11».","g":"informativo"},{"t":"Embora o registro de DAYVIGO® já tenha sido concedido pela Anvisa, o medicamento estará apto para comercialização após a aprovação do preço máximo pela Câmara de Regulação do Mercado de Medicamentos (CMED). Porém, a decisão de quando o medicamento será comercializado é da empresa detentora do registro.","g":"informativo"}],"rx":[{"id":"l028-lemborexante-5mg-com-rev","t":"Lemborexante 5 mg","p":"Lemborexante 5 mg/comprimido revestido — 30 comprimidos/mês.\nTomar 1 comprimido, via oral, 1 vez ao dia, à noite.","o":"A dose recomendada de DAYVIGO® é de 5 mg, administrada não mais que uma vez por noite, e alguns minutos antes de ir para a cama, com pelo menos 7 horas restantes antes da hora planejada de despertar. O tempo para o início do sono pode demorar, se administrado logo após ou com uma refeição.","fo":"ANVISA — «Dayvigo® (lemborexante): novo registro», gov.br/anvisa, seção Medicamentos > Novos medicamentos e indicações, publicado em 07/04/2025 e modificado em…","dt":"receita_controle_especial"},{"id":"l028-lemborexante-10mg-com-rev","t":"Lemborexante 10 mg","p":"Lemborexante 10 mg/comprimido revestido — 30 comprimidos/mês.\nTomar 1 comprimido, via oral, 1 vez ao dia, à noite.","o":"A dose máxima recomendada de DAYVIGO® é de 10 mg, uma vez ao dia. DAYVIGO® deve ser utilizado na dose mais baixa e durante o menor período, conforme clinicamente indicado.","fo":"ANVISA — «Dayvigo® (lemborexante): novo registro», gov.br/anvisa, seção Medicamentos > Novos medicamentos e indicações, publicado em 07/04/2025 e modificado em…","dt":"receita_controle_especial"}]},{"k":"ramelteona","n":"ramelteona","atc":"N05CH02","cs":"2 braços","ap":[{"c":"8 mg","f":"comprimido revestido","v":"oral","l":null,"r":false}],"mc":["RAHIME","RAMELTEONA","ROZEREM"],"d":{"i":"A dose recomendada de ramelteona é um comprimido (8 mg), por via oral, 30 minutos antes de deitar","u":"A dose recomendada de ramelteona é um comprimido (8 mg), por via oral, 30 minutos antes de deitar","m":"A dose recomendada não deve exceder a 1 comprimido (8 mg) por dia","fr":"dose única, 30 minutos antes de deitar; não deve ser tomado durante ou imediatamente após uma refeição com alto teor de gordura","fo":"bula ramelteona, linhas 542–545"},"rn":{"t":"Não são necessários ajustes da dose para pacientes com função renal comprometida.","fo":"bula ramelteona, linhas 554–573"},"hp":{"t":"Não são necessários ajustes da dose para pacientes com insuficiência hepática leve a moderada. Entretanto, é recomendada cautela quando a ramelteona for administrada a pacientes com insuficiência hepática moderada porque o aumento de exposição ao medicamento foi maior nestes indivíduos. Rahime® (ramelteona) não é recomendado para pacientes com insuficiência hepática grave.","fo":"bula ramelteona, linhas 554–573"},"ge":{"t":"Não existem estudos adequados e bem controlados em mulheres grávidas. Rahime® (ramelteona) só deve ser utilizada durante a gravidez se o benefício potencial justificar o risco potencial ao feto. A ramelteona está classificada na categoria C de risco na gravidez.","fo":"bula ramelteona, linhas 324–325"},"am":{"t":"O uso deste medicamento em mulheres que estão amamentando não é recomendado. Não se sabe se ramelteona é excretada no leite humano; no entanto, ramelteona é excretada no leite de ratas em lactação. Como muitas drogas são excretadas no leite humano, é necessário cuidado quando administrada a mulheres que estejam amamentando.","fo":"bula ramelteona, linhas 347–350"},"pe":{"t":"A segurança e a eficácia de ramelteona em pacientes pediátricos não foram estabelecidas. A ramelteona não foi estudada em adolescentes e crianças.","fo":"texto extraído com `pdftotext -layout` do PDF oficial, ambos…"},"al":[{"t":"4. CONTRAINDICAÇÕES\n• Hipersensibilidade conhecida, incluindo reações anafiláticas e anafilactóides graves a ROZEREM ou a qualquer\n     dos componentes deste medicamento.\n• Os pacientes não devem tomar este medicamento em conjunto com fluvoxamina (inibidor potente da CYP1A2),\n     pois ocorre aumento da ASC do ramelteona, e ambos não devem ser utilizados em associação.","g":"aviso"},{"t":"Em estudos clínicos que suportam eficácia, ROZEREM (ramelteona) foi utilizado por até 6 meses em um estudo.\nNeste estudo, a avaliação formal final da latência do sono foi realizada no final do mês 6 e foi observada eficácia.\nAs avaliações finais formais da latência do sono foram realizadas após 2 dias de tratamento durante o estudo\ncruzado (somente para idosos) e em 5 semanas nos estudos de 6 semanas (adultos e idosos). Foi observada\neficácia também nestes momentos. É recomendado que ROZEREM (ramelteona) seja tomado por não mais de 5\nsemanas. Em alguns casos, pode ser necessário manter o tratamento por um período mais longo. Isso só deve ser\nfeito após uma reavaliação da condição clínica do paciente.","g":"aviso"},{"t":"Ramelteona consta da Lista C1 da Portaria SVS/MS 344/98, atualizada pela RDC 1.036/2026.","g":"aviso"},{"t":"Controle especial: ramelteona consta da Lista C1 da Portaria SVS/MS nº 344, de 12 de maio de 1998, no item «169.Ramelteona». Informação de dispensação — quem escolhe o tipo de receita no aplicativo é o médico.","g":"aviso"},{"t":"4. CONTRA-INDICAÇÕES\nHipersensibilidade conhecida, incluindo reações anafiláticas e anafilactoides graves a Rahime® (ramelteona) ou a\nqualquer dos componentes deste medicamento.\nOs pacientes não devem tomar este medicamento em conjunto com fluvoxamina (inibidor potente da CYP1A2), pois\nocorre aumento da ASC do ramelteona, e ambos não devem ser utilizados em associação.\n\nEste medicamento não deve ser usado por pessoas com síndrome de má-absorção de glicose-galactose.","g":"contraindicacao"},{"t":"Comportamentos complexos como “dirigir enquanto dorme” (i.e., dirigir sem estar totalmente acordado após a\ningestão de um hipnótico) e outros comportamentos complexos (por exemplo, preparar e comer alimentos, fazer\nligações telefônicas ou ter relações sexuais), com amnésia em relação ao evento, foram relatados em associação ao\nuso de hipnóticos. O uso de álcool e de outros depressores do SNC pode aumentar o risco de tais comportamentos.\nEstes eventos podem ocorrer tanto em pessoas que nunca usaram hipnóticos quanto naquelas que já usaram\nhipnóticos. Comportamentos complexos foram relatados com o uso de ramelteona nos EUA. A descontinuação de\nramelteona deve ser fortemente considerada em pacientes que relatam algum comportamento complexo do sono.","g":"alta"},{"t":"Os pacientes devem evitar atividades perigosas que requeiram concentração (como dirigir veículo ou operar\nmáquinas pesadas), após tomar este medicamento.\nDepois de tomar ramelteona, os pacientes devem limitar suas atividades às necessárias para se preparar para\ndormir. Devido suas propriedades especificamente dirigidas a promover o sono, este medicamento deve ser tomado","g":"aviso"},{"t":"também nestes momentos. É recomendado que ramelteona seja tomada por não mais de 5 semanas. Em alguns\ncasos, pode ser necessário manter o tratamento por um período mais longo. Isso só deve ser feito após uma\nreavaliação da condição clínica do paciente.","g":"aviso"},{"t":"VENDA SOB PRESCRIÇÃO - COM RETENÇÃO DE RECEITA.","g":"aviso"}],"rx":[{"id":"l028-ramelteona-convencional-8-mg-com-rev","t":"Ramelteona 8 mg — comprimido revestido","p":"Ramelteona 8 mg/comprimido revestido — 30 comprimidos/mês.\nTomar 1 comprimido, via oral, 1 vez ao dia.","o":"Tomar 30 minutos antes de deitar. Não tomar durante ou imediatamente após uma refeição com alto teor de gordura. Não prolongar além de 5 semanas sem reavaliação.","fo":"rozerem.txt — Takeda Pharma Ltda.; ROZEREM profissional; código RO_COM_1119_0523_VPS (05/2023); 8. Posologia e modo de usar; página PDF 8; linhas 508-522 de…","dt":"receita_controle_especial"},{"id":"l028-ramelteona-8mg-com-rev","t":"Ramelteona 8 mg","p":"Ramelteona 8 mg/comprimido revestido — 30 comprimidos/mês.\nTomar 1 comprimido, via oral, 1 vez ao dia, 30 minutos antes de deitar.","o":"Rahime® (ramelteona) não deve ser tomado durante ou imediatamente após uma refeição com alto teor de gordura.","fo":"Bula do profissional — RAHIME® (ramelteona), comprimido revestido 8 mg, Apsen Farmacêutica S.A., Registro 1.0118.0636 · bula-ramelteona.txt, linhas 542–545…","dt":"receita_controle_especial"}]},{"k":"aripiprazol","n":"aripiprazol","atc":"N05AX12","cs":"2 braços","ap":[{"c":"15 mg","f":"comprimido","v":"oral","l":null,"r":false},{"c":"10 mg","f":"comprimido","v":"oral","l":null,"r":false},{"c":"20 mg/mL","f":"suspensão oral em gotas","v":"oral","l":null,"r":false},{"c":"20 mg","f":"comprimido","v":"oral","l":null,"r":false},{"c":"30 mg","f":"comprimido","v":"oral","l":null,"r":false},{"c":"1 mg/mL","f":"suspensão oral","v":"oral","l":null,"r":false},{"c":"10 mg","f":"comprimido orodispersível","v":"oral","l":null,"r":false},{"c":"15 mg","f":"comprimido orodispersível","v":"oral","l":null,"r":false},{"c":"20 mg","f":"comprimido orodispersível","v":"oral","l":null,"r":false},{"c":"30 mg","f":"comprimido orodispersível","v":"oral","l":null,"r":false},{"c":"20 mg/mL","f":"solução oral em gotas","v":"oral","l":null,"r":false}],"mc":["AIPRI","AQUARELA","ARIPIPRAZOL","ARISTAB","ARISTAB ODT","ARPEJO","ARPIO","BIQUIZ"],"d":{"i":"A dose de início e a dose alvo recomendadas para Harip é de 10 mg/dia ou 15 mg/dia uma vez ao dia, independente das refeições","u":"Aripiprazol tem sido avaliado sistematicamente e demonstrou ser eficaz em uma variação de dose entre 10 mg/dia e 30 mg/dia","m":"doses superiores a 10 mg/dia ou 15 mg/dia não foram mais eficazes; no transtorno bipolar a dose pode ser elevada para 30 mg/dia e a segurança das doses superiores a 30 mg/dia não foi avaliada em estudos clínicos","fr":"uma vez ao dia","fo":"bula aripiprazol, linhas 546–547"},"rn":{"t":"Ajuste da Dosagem\nAjustes da dosagem em adultos não são habitualmente indicados de acordo com a idade, sexo, raça ou estado da\ninsuficiência renal ou hepática","fo":"aripiprazol novartis profissional · Ajuste de dosagem"},"hp":{"t":"Ajuste da Dosagem\nAjustes da dosagem em adultos não são habitualmente indicados de acordo com a idade, sexo, raça ou estado da\ninsuficiência renal ou hepática","fo":"aripiprazol novartis profissional · Ajuste de dosagem"},"ge":{"t":"Uso em populações específicas\n- Gravidez\nCategoria C: As evidências disponíveis são inconclusivas ou inadequadas para determinar o risco fetal quando\nusadas em mulheres grávidas ou em potencial para engravidar. Em estudos com animais, o aripiprazol demonstrou\ntoxicidade do desenvolvimento, incluindo possíveis efeitos teratogênicos em ratos e coelhos.","fo":"aripiprazol novartis profissional · Gravidez"},"am":{"t":"- Uso por lactantes\nAripiprazol é excretado no leite materno humano.","fo":"aripiprazol novartis profissional · Uso por lactantes"},"pe":{"t":"Uso pediátrico: não há indicação aprovada para o uso de aripiprazol em pacientes pediátricos.","fo":"Bula do profissional · texto extraído com `pdftotext -layout` do PDF oficial, ambos…"},"al":[{"t":"4. CONTRAINDICAÇÕES\nO aripiprazol é contraindicado para pacientes que são hipersensíveis ao aripiprazol ou qualquer um dos seus\nexcipientes. As reações variaram de prurido/urticária a anafilaxia [vide 9. REAÇÕES ADVERSAS].","g":"aviso"},{"t":"- Ajuste da dosagem para pacientes recebendo aripiprazol concomitantemente a inibidores fortes de CYP3A4.\nQuando for indicada a administração concomitante de aripiprazol com inibidores fortes de CYP3A4, como\ncetoconazol ou claritromicina, a dose de aripiprazol deve ser reduzida para a metade da dose habitual.\n\nQuando um inibidor de CYP3A4 for retirado da terapia combinada, a dose de aripiprazol deve ser então elevada [vide\n6. INTERAÇÕES MEDICAMENTOSAS].\n\n- Ajuste da dosagem para pacientes recebendo aripiprazol concomitantemente a inibidores de CYP2D6 em\npotencial.\n\nQuando ocorrer a administração concomitante de aripiprazol com inibidores de CYP2D6 em potencial, como\nquinidina, fluoxetina ou paroxetina, a dose de aripiprazol deve ser reduzida, no mínimo, até a metade de sua dose\nnormal. Quando um inibidor de CYP2D6 for retirado da terapia combinada, a dose de aripiprazol deve ser então\nelevada\n\n- Ajuste da dosagem para pacientes recebendo indutores de CYP3A4 em potencial.\nQuando um indutor de CYP3A4 em potencial, como carbamazepina, é incluído na terapia com aripiprazol, a dose de\naripiprazol deve ser dobrada. Aumentos adicionais na dose devem ser baseados na avaliação clínica. Quando um\nindutor de CYP3A4 for retirado da terapia combinada, a dose de aripiprazol deve ser reduzida para 10 mg ou 15 mg\n\n- Ajuste de dosagem para pacientes metabolizadores pobres de substratos de CYP2D6. A dose habitual de\naripiprazol deve ser reduzida pela metade em pacientes metabolizadores pobres de substratos de CYP2D6. Ajustes\nadicionais podem ser necessários com base na avaliação clínica.\n","g":"aviso"},{"t":"Aripiprazol consta da Lista C1 da Portaria SVS/MS 344/98, atualizada pela RDC 1.036/2026.","g":"aviso"},{"t":"Controle especial: aripiprazol consta da Lista C1 da Portaria SVS/MS nº 344, de 12 de maio de 1998, no item «8.Aripiprazol». Informação de dispensação — quem escolhe o tipo de receita no aplicativo é o médico.","g":"aviso"},{"t":"O Harip é contraindicado para pacientes que são hipersensíveis ao aripiprazol ou qualquer um dos seus excipientes. As reações variaram de\nprurido/urticária a anafilaxia (vide 9. REAÇÕES ADVERSAS).","g":"contraindicacao"},{"t":"Aumento da mortalidade em pacientes idosos com psicose associada à demência: deve-se evitar a utilização em pacientes idosos com\npsicose associada à demência tratados com drogas antipsicóticas correm maior risco de morte. Análises de dezessete estudos controlados por\nplacebo (duração modal de dez semanas) basicamente em pacientes que recebiam drogas antipsicóticas atípicas revelou risco de morte em\npacientes tratados com drogas de 1,6 a 1,7 vezes maior que em pacientes tratados com placebo. Apesar das causas das mortes serem variadas,\na maioria dos óbitos pareceu ter natureza cardiovascular (como insuficiência cardíaca, morte súbita) ou infecciosa (como pneumonia). O\nHarip (aripiprazol) não é aprovado para tratamento de pacientes com psicose associada à demência.","g":"alta"},{"t":"Uso geriátrico: não há necessidade de ajuste de dose em pacientes idosos. Em estudos formais de farmacocinética de dose única (com\naripiprazol administrado em dose única de 15 mg), o clearance do aripiprazol foi 20% menor em indivíduos idosos (≥ 65 anos) em\ncomparação a indivíduos adultos mais jovens (18 a 64 anos). No entanto, não houve efeito detectável atribuível à idade na análise de","g":"aviso"},{"t":"Este medicamento não deve ser partido, aberto ou mastigado.","g":"aviso"},{"t":"VENDA SOB PRESCRIÇÃO MÉDICA\nSÓ PODE SER VENDIDO COM RETENÇÃO DA RECEITA","g":"aviso"}],"rx":[{"id":"l028-aripiprazol-convencional-15-mg-com","t":"Aripiprazol 15 mg — comprimido","p":"Aripiprazol 15 mg/comprimido — 30 comprimidos/mês.\nTomar 1 comprimido, via oral, 1 vez ao dia.","o":"","fo":"aripiprazol-novartis-profissional.txt — Posologia: Esquizofrenia; páginas PDF 12-13; linhas 754-760; Novartis, VPS04; atualizada conforme Bula Padrão Anvisa de…","dt":"receita_controle_especial"},{"id":"l028-aripiprazol-convencional-10-mg-com","t":"Aripiprazol 10 mg — comprimido","p":"Aripiprazol 10 mg/comprimido — 30 comprimidos/mês.\nTomar 1 comprimido, via oral, 1 vez ao dia.","o":"","fo":"aripiprazol-novartis-profissional.txt — Posologia: Esquizofrenia; páginas PDF 12-13; linhas 754-760; Novartis, VPS04; atualizada conforme Bula Padrão Anvisa de…","dt":"receita_controle_especial"},{"id":"l028-aripiprazol-convencional-1-mg-ml-sus-or","t":"Aripiprazol 1 mg/mL — suspensão oral","p":"Aripiprazol 1 mg/mL/suspensão oral — 300 mL/mês.\nTomar 10 mL, via oral, 1 vez ao dia.","o":"Agite antes de usar. Utilize a seringa dosadora que acompanha o frasco.","fo":"aristab-suspensao.txt — Aché, Aristab suspensão oral 1 mg/mL, BU04 VPS PE; bula-padrão aprovada em 14/02/2022, PDF página 11, linhas 779-782…","dt":"receita_controle_especial"}]}])}catch(e){}})();
